import { query } from '../db.js';
import { OrderRepository } from '../repositories/order-repository.js';

const orderRepository = new OrderRepository();

// Callback-style database access. Chapter 5 migrates this to OrderRepository.
export function listOrdersForUser(userId, callback) {
  query('orders', (o) => o.user_id === userId && o.deleted_at === null, callback);
}

export function totalPaidCents(callback) {
  query('orders', (o) => o.status === 'paid' && o.deleted_at === null, (err, rows) => {
    if (err) return callback(err);
    callback(null, rows.reduce((sum, o) => sum + o.total_cents, 0));
  });
}

// Callback-style export backed by the repository. The two-argument then() keeps
// an error thrown inside the callback from triggering a second callback call.
export function countPaidOrders(callback) {
  orderRepository.findPaid().then(
    (rows) => callback(null, rows.length),
    (err) => callback(err),
  );
}
EOF
cat >> tests/order-service.test.js <<'EOF'

test('countPaidOrders counts only paid, non-deleted orders', (t, done) => {
  countPaidOrders((err, count) => {
    assert.equal(err, null);
    assert.equal(count, 3);
    done();
  });
});
EOF
